// zod 4's normalizeParams on an instance method, behind a package declaration.
function normalizeParams(params) {
  if (params?.message !== undefined) params.error = params.message;
  delete params.message;
  return params;
}
export function schema(name) {
  const inst = { name };
  inst.refine = (label, params) => `${inst.name}.${label}: ${JSON.stringify(normalizeParams(params))}`;
  return inst;
}
